source.write_text('''"""Conservative triage of read-only ATS field metadata (never answers or submits)."""
from __future__ import annotations

import re
from typing import Any, Mapping

_CONTACT = {
    "full_name": re.compile(r"^full\\\\s+name\\\\s*[*✱]?$",re.I),
    "email": re.compile(r"^(?:e-?mail|email address)\\\\s*[*✱]?$",re.I),
    "phone": re.compile(r"^(?:phone|phone number|mobile|telephone)\\\\s*[*✱]?$",re.I),
    "linkedin": re.compile(r"^(?:linkedin(?: url| profile)?)\\\\s*[*✱]?$",re.I),
    "github": re.compile(r"^(?:github(?: url| profile)?)\\\\s*[*✱]?$",re.I),
}
def classify_field(field: Mapping[str, Any], verified_keys: set[str] | frozenset[str]) -> dict[str, str]:
    """Return a routing decision, not an answer. Unknowns always require review.

    Verified keys grant only *candidate mapping*, never automatic form filling.
    """
    question = re.sub(r"\\\\s+", " ", str(field.get("question") or field.get("label") or "")).strip()
    label = re.sub(r"\\\\s+", " ", str(field.get("label") or "")).strip()
    kind = str(field.get("type") or "").lower()
    if bool(field.get("ambiguous")) or not question:
        return {"status":"human_review","reason":"ambiguous_question"}
    if kind in {"checkbox","radio","select-one","select-multiple","textarea","file","password"}:
        return {"status":"human_review","reason":"nontrivial_control"}
    for key, pattern in _CONTACT.items():
        if pattern.fullmatch(question) and (not label or pattern.fullmatch(label)):
            if key in verified_keys:
                return {"status":"verified_candidate","profile_key":key}
            return {"status":"human_review","reason":"unverified_profile_fact"}
    return {"status":"human_review","reason":"unknown_question"}

def triage_fields(fields: list[Mapping[str, Any]], verified_keys: set[str] | frozenset[str]) -> list[dict[str, str]]:
    return [classify_field(field,verified_keys) for field in fields]
''')
test.write_text('''import pytest
from tools.ats_question_triage import classify_field,triage_fields

@pytest.mark.parametrize("question,kind",[
    ("Will you require sponsorship?","radio"),
    ("Do you use AI in your role?","radio"),
    ("Why are you interested in joining Ethena?","textarea"),
    ("I acknowledge that I have read the employer AI policy.","checkbox"),
    ("Which location are you based in?","select-one"),
    ("Resume/CV","file"),
    ("Current company name","text"),
    ("Full name of referee","text"),
])
def test_unknown_or_sensitive_never_autofills(question,kind):
    out=classify_field({"question":question,"label":"","type":kind,"ambiguous":False,"required":True},{"full_name","email","phone"})
    assert out["status"]=="human_review"

def test_only_exact_verified_contact_field_is_candidate():
    fields=[{"question":"Full name ✱","label":"Full name ✱","type":"text","ambiguous":False},
            {"question":"Email ✱","label":"Email ✱","type":"email","ambiguous":False},
            {"question":"Email ✱","label":"Email ✱","type":"email","ambiguous":True},
            {"question":"Phone ✱","label":"Phone ✱","type":"text","ambiguous":False}]
    out=triage_fields(fields,{"full_name","email"})
    assert [x["status"] for x in out]==["verified_candidate","verified_candidate","human_review","human_review"]
    assert out[0]["profile_key"]=="full_name"
    assert out[3]["reason"]=="unverified_profile_fact"

def test_yes_no_label_not_treated_as_question():
    assert classify_field({"label":"Yes","type":"radio","ambiguous":True},{"full_name"})["status"]=="human_review"
''')
